-- 028: curation fields. commercial = low/medium/high, ccd_fit = 0-100 vs the Ep 03/04 taste, verify_note = web check summary.
alter table public.artists add column if not exists commercial text check (commercial in ('low','medium','high'));
alter table public.artists add column if not exists ccd_fit int check (ccd_fit between 0 and 100);
alter table public.artists add column if not exists verified_at timestamptz;
alter table public.artists add column if not exists verify_note text;
create or replace function pg_temp.cur(s text, c text, f int, n text) returns void language sql as $$
  update public.artists set commercial=c, ccd_fit=f, verify_note=n, verified_at=now() where slug=s $$;
